{/* VI. CAPACIDADES SENSOPERCEPTIVAS */}
{/* ========================================================= */}

<h4 className="mt-5 mb-3">VI. Capacidades Sensoperceptivas</h4>

<p className="text-muted">
  Marque la opción que corresponda: S = Siempre (1), G = Generalmente (2), O = Ocasionalmente (3), N = Nunca (4), N/O = No Observado (0).
</p>

<table className="table table-bordered align-middle">
  <thead className="table-secondary text-center">
    <tr>
      <th style={{ width: "60%" }}>Ítem</th>
      <th>S<br />1</th>
      <th>G<br />2</th>
      <th>O<br />3</th>
      <th>N<br />4</th>
      <th>N/O<br />0</th>
    </tr>
  </thead>

  <tbody>
    {ITEMS_SENSOPERCEPTIVAS.map((item) => (
      <tr key={item.id}>
        <td>{item.descripcion}</td>

        {[1, 2, 3, 4, 0].map((valor) => (
          <td key={valor} className="text-center">
            <input
              type="radio"
              name={`sensoperceptivas-${item.id}`}
              checked={valoresSensoperceptivas[item.id] === valor}
              onChange={() =>
                handleRadioSensoperceptivas(item.id, valor)
              }
            />
          </td>
        ))}
      </tr>
    ))}
  </tbody>
</table>

