    <div className="mt-4 p-3 border bg-white rounded">
  <h4 className="mb-3">C. SUBSECTORES</h4>
  <p>Marque donde el/la estudiante se <b>destaca</b> o presenta <b>dificultad</b>.</p>

  {/* EDUCACIÓN PARVULARIA */}
  <h5 className="mt-3 text-primary">Educación Parvularia</h5>
  {SUBSECTORES.parvularia.map((sub) => (
    <div key={sub} className="d-flex align-items-center mb-2">
      <span className="me-3" style={{ width: "280px" }}>{sub}</span>

      <label className="me-3">
        <input
          type="checkbox"
          checked={subsectoresSeleccionados[sub] === "destacado"}
          onChange={() => handleSubsector(sub, "destacado")}
        />{" "}
        ✔ Destacado
      </label>

      <label>
        <input
          type="checkbox"
          checked={subsectoresSeleccionados[sub] === "dificultad"}
          onChange={() => handleSubsector(sub, "dificultad")}
        />{" "}
        ✘ Dificultad
      </label>
    </div>
  ))}

  {/* EDUCACIÓN BÁSICA */}
